import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, smoothstep, float, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, AdditiveBlending, DoubleSide, SRGBColorSpace } = THREE;

  const group = new Group();
  group.name = 'floating-accent-sprite';

  const timelines = [];
  const cleanups = [];

  // ---- Atlas-rect geometry (512 x 320 => aspect 1.6) ----
  const atlasW = 512;
  const atlasH = 320;
  const planeH = 3.2;
  const planeW = planeH * (atlasW / atlasH); // 5.12

  const geo = new PlaneGeometry(planeW, planeH);
  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
    toneMapped: true,
  });
  const spriteMesh = new Mesh(geo, mat);
  spriteMesh.renderOrder = 2;
  group.add(spriteMesh);

  // ---- Accent glow halo behind sprite (depth plane, signal-red) ----
  const haloGeo = new PlaneGeometry(planeW * 1.45, planeH * 1.45);
  const haloMat = new MeshBasicNodeMaterial({
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
    side: DoubleSide,
    toneMapped: true,
  });
  {
    const cu = uv().sub(0.5);
    const dist = cu.length();
    const fall = float(1.0).sub(smoothstep(0.0, 0.5, dist));
    haloMat.colorNode = vec3(1.0, 0.165, 0.22).mul(fall).mul(0.16);
  }
  const haloMesh = new Mesh(haloGeo, haloMat);
  haloMesh.position.z = -0.1;
  haloMesh.renderOrder = 1;
  group.add(haloMesh);

  // ---- Radial contact-shadow plane (grounding) ----
  const shadowGeo = new PlaneGeometry(planeW * 1.15, 1.1);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    toneMapped: true,
  });
  {
    const suv = uv().sub(0.5);
    const sdist = suv.length();
    const sf = float(1.0).sub(smoothstep(0.0, 0.5, sdist));
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0).mul(sf).mul(0.5);
  }
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.y = -planeH * 0.56;
  shadowMesh.position.z = -0.02;
  shadowMesh.renderOrder = 0;
  group.add(shadowMesh);

  // ---- Load sprite texture (async, cached) ----
  let loadedTex = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = SRGBColorSpace;
    tex.anisotropy = 4;
    loadedTex = tex;
    mat.colorNode = texture(tex, uv());
  }).catch(() => {
    // graceful fallback tint so the plane never reads as flat void
    mat.colorNode = vec3(1.0, 0.165, 0.22).mul(0.35);
  });

  // ---- Entrance: weighted-settle scale + fade-up ----
  group.scale.set(0.96, 0.96, 0.96);

  const scaleTl = gsap.timeline();
  scaleTl.to(group.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(scaleTl);

  const fadeTl = gsap.timeline();
  fadeTl.fromTo(mat, { opacity: 0 }, { opacity: 1, duration: 0.7, ease: 'power2.out' }, 0);
  fadeTl.fromTo(haloMat, { opacity: 0 }, { opacity: 1, duration: 0.9, ease: 'power2.out' }, 0.15);
  fadeTl.fromTo(shadowMat, { opacity: 0 }, { opacity: 1, duration: 0.8, ease: 'power2.out' }, 0.2);
  timelines.push(fadeTl);

  // ---- Billboard hook (defensive: parent/camera may move) ----
  group.userData.update = (camera) => {
    if (camera) group.quaternion.copy(camera.quaternion);
  };

  // ---- Event handlers (none per spec, but surface must exist) ----
  group.userData.handlers = {};

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    cleanups.forEach((fn) => { try { fn(); } catch (_) {} });
    geo.dispose();
    haloGeo.dispose();
    shadowGeo.dispose();
    mat.dispose();
    haloMat.dispose();
    shadowMat.dispose();
    if (loadedTex && loadedTex.dispose) loadedTex.dispose();
  };

  return group;
}
